using System;using System.IO;using System.Linq;using System.Collections.Generic;
internal sealed class PreviewCoverBinding {
 public int Version{get;set;}public string SourceType{get;set;}public string ResourceSha256{get;set;}public string ImageSha256{get;set;}public string ImageRelative{get;set;}public int Width{get;set;}public int Height{get;set;}public string CreatedAt{get;set;}public string RunId{get;set;}public string RunRelative{get;set;}public int PlayerPid{get;set;}public long PlayerCreation{get;set;}public long Window{get;set;}public long Render{get;set;}public string PlayerImageSha256{get;set;}public string CaptureMethod{get;set;}public string Region{get;set;}public string InitiatedBy{get;set;}
}
// A supplementary picture, never playback acceptance. No ID/name-based lookup and no catalog mutation.
internal static class PreviewCovers {
 internal const string Kind="preview-screenshot";
 sealed class Identity{internal string Hash,Signature;}
 static readonly Dictionary<string,Identity> verified=new Dictionary<string,Identity>(StringComparer.OrdinalIgnoreCase);static readonly object gate=new object();
#if TEST_BUILD
 internal static void TestForgetIdentities(){lock(gate)verified.Clear();}
#endif
 internal static void NoteIdentity(string source,string hash,string signature){lock(gate)verified[source]=new Identity{Hash=hash,Signature=signature};}
 internal static bool IdentityMatches(WallpaperItem item){try{if(item==null||!PackageAnalysis.HashText(item.RegisteredSha256)||!File.Exists(item.SourcePath))return false;Identity known;lock(gate){if(!verified.TryGetValue(item.SourcePath,out known))return false;}return known.Hash==item.RegisteredSha256&&known.Signature==CoverCache.Signature(item.SourcePath);}catch{return false;}}
 static string Folder(string hash){if(!PackageAnalysis.HashText(hash))throw new InvalidDataException("识别图需要完整SHA-256");return Path.Combine(Common.Root,"data","preview-covers",hash.ToLowerInvariant());}
 internal static string ImagePath(PreviewCoverBinding b){if(b==null||Path.IsPathRooted(b.ImageRelative))return null;string p=Path.GetFullPath(Path.Combine(Common.Root,b.ImageRelative));return LocalImport.Under(p,Folder(b.ResourceSha256))?p:null;}
 internal static PreviewCoverBinding Resolve(string hash){try{string folder=Folder(hash),meta=Path.Combine(folder,"binding.json");if(!File.Exists(meta)||new FileInfo(meta).Length>32768)return null;var b=Common.Json.Deserialize<PreviewCoverBinding>(Common.ReadShared(meta));if(b.Version!=1||b.SourceType!=Kind||b.ResourceSha256!=hash||b.Width<1||b.Height<1||b.Width>480||b.Height>300)return null;string p=ImagePath(b);if(p==null||!File.Exists(p)||new FileInfo(p).Length>2097152||Common.Hash(p)!=b.ImageSha256)return null;LocalImport.NoLinks(p);return b;}catch{return null;}}
 internal static PreviewCoverBinding ForItem(WallpaperItem item){return IdentityMatches(item)?Resolve(item.RegisteredSha256):null;}
 internal static bool HasIndependentCover(WallpaperItem item){if(item==null)return false;if(!String.IsNullOrEmpty(item.CoverPath)&&File.Exists(item.CoverPath))return true;try{string hash=item.RegisteredSha256;if(!PackageAnalysis.HashText(hash))return false;string folder=Path.Combine(Common.Root,"data","cover-cache",hash),meta=Path.Combine(folder,"cover.json"),image=Path.Combine(folder,"thumbnail.jpg");if(!File.Exists(meta)||!File.Exists(image)||new FileInfo(meta).Length>65536)return false;var b=Common.Json.Deserialize<CoverBinding>(Common.ReadShared(meta));return b.Sha256==hash&&b.ThumbnailSha256==Common.Hash(image);}catch{return false;}}
 internal static string Stamp(WallpaperItem item){if(item==null||!IdentityMatches(item))return "identity-unmatched";try{string p=Path.Combine(Folder(item.RegisteredSha256),"binding.json");return File.Exists(p)?File.GetLastWriteTimeUtc(p).Ticks.ToString():"none";}catch{return "none";}}
 internal static void Attach(CandidateCheckResult result){if(!PackageAnalysis.HashText(result.Sha256))return;if(result.CoverRelative!=null&&result.CoverKind!=Kind)return;var b=Resolve(result.Sha256);if(b==null){if(result.CoverKind==Kind){result.CoverRelative=null;result.CoverSha256=null;result.CoverKind=null;result.CoverReason="预览截图不可用，原包无可靠图片";}return;}result.CoverRelative=b.ImageRelative;result.CoverSha256=b.ImageSha256;result.CoverKind=Kind;result.CoverReason="预览截图 · 用户生成识别图，不是官方或包内封面";result.CoverMember=null;}
 internal static PreviewCoverBinding Publish(string input,PreviewFrameTarget target,string expectedImageHash,int width,int height,string method,string initiatedBy,bool replace,Action guard){
  guard();if(!PackageAnalysis.HashText(target.ResourceSha256)||!LocalImport.Under(target.Run,Path.Combine(Common.Root,"logs")))throw new InvalidDataException("识别图资源或预览运行身份无效");if(new FileInfo(input).Length>2097152||Common.Hash(input)!=expectedImageHash)throw new InvalidDataException("捕获图片哈希或大小不符");byte[] bytes=File.ReadAllBytes(input);var size=CoverCache.ImageDimensions(bytes);if(size.Width!=width||size.Height!=height||width>480||height>300)throw new InvalidDataException("识别图尺寸超出预算");using(var stream=new MemoryStream(bytes,false))using(var im=System.Drawing.Image.FromStream(stream,true,true)){if(im.Width!=width||im.Height!=height)throw new InvalidDataException("图片不可读取");}
  var old=Resolve(target.ResourceSha256);if(old!=null&&!replace)throw new InvalidOperationException("已有预览截图，需要明确选择替换");
  string folder=Folder(target.ResourceSha256);Directory.CreateDirectory(folder);LocalImport.NoLinks(folder);string id=Guid.NewGuid().ToString("N").Substring(0,16),image=Path.Combine(folder,"f-"+id+".jpg"),temp=Path.Combine(folder,Guid.NewGuid().ToString("N").Substring(0,8)+".tmp"),meta=Path.Combine(folder,"binding.json"),metaTemp=Path.Combine(folder,Guid.NewGuid().ToString("N").Substring(0,8)+".tmp");bool committed=false,tempCreated=false,metaCreated=false,imageCreated=false;
  if(image.Length>=260||temp.Length>=260||metaTemp.Length>=260||folder.Length>=248)throw new PathTooLongException("当前数据位置过长，未保存截图封面；原封面保留");
  try{using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){tempCreated=true;output.Write(bytes,0,bytes.Length);}guard();if(Common.Hash(temp)!=expectedImageHash)throw new InvalidDataException("临时识别图校验失败");File.Move(temp,image);imageCreated=true;
   var b=new PreviewCoverBinding{Version=1,SourceType=Kind,ResourceSha256=target.ResourceSha256,ImageSha256=expectedImageHash,ImageRelative=image.Substring(Common.Root.TrimEnd('\\').Length+1),Width=width,Height=height,CreatedAt=DateTimeOffset.Now.ToString("o"),RunId=Path.GetFileName(target.Run),RunRelative=target.Run.Substring(Common.Root.TrimEnd('\\').Length+1),PlayerPid=target.PlayerPid,PlayerCreation=target.PlayerCreation,Window=target.Window,Render=target.Render,PlayerImageSha256=Common.HostHash,CaptureMethod=method,Region="own-preview-render-client",InitiatedBy=initiatedBy};
   Common.SaveNew(metaTemp,b);metaCreated=true;guard();if(File.Exists(meta))File.Replace(metaTemp,meta,null);else File.Move(metaTemp,meta);committed=true;return b;
  }finally{if(tempCreated&&File.Exists(temp))File.Delete(temp);if(metaCreated&&File.Exists(metaTemp))File.Delete(metaTemp);if(!committed&&imageCreated&&File.Exists(image))File.Delete(image);}
 }
}
